11|/**
12| * This fuzz target performs a zstd round-trip test (compress & decompress),
13| * compares the result with the original, and calls abort() on corruption.
14| */
15|
16|#define ZSTD_STATIC_LINKING_ONLY
17|
18|#include <stddef.h>
19|#include <stdlib.h>
20|#include <stdio.h>
