865|/** ZSTD_ipow() :
866| * Return base^exponent.
867| */
868|static U64 ZSTD_ipow(U64 base, U64 exponent)
869|{
870|    U64 power = 1;
871|    while (exponent) {
872|      if (exponent & 1) power *= base;
873|      exponent >>= 1;
874|      base *= base;
875|    }
876|    return power;
