895|/** ZSTD_rollingHash_compute() :
896| * Compute the rolling hash value of the buffer.
897| */
898|MEM_STATIC U64 ZSTD_rollingHash_compute(void const* buf, size_t size)
899|{
900|    return ZSTD_rollingHash_append(0, buf, size);
