1324|MEM_STATIC double ZSTD_fWeight(U32 rawStat)
1325|{
1326|    U32 const fp_accuracy = 8;
1327|    U32 const fp_multiplier = (1 << fp_accuracy);
1328|    U32 const newStat = rawStat + 1;
1329|    U32 const hb = ZSTD_highbit32(newStat);
