1039|    if (ZSTD_WINDOW_OVERFLOW_CORRECT_FREQUENTLY) {
1040|        if (ZSTD_window_canOverflowCorrect(window, cycleLog, maxDist, loadedDictEnd, src)) {
1041|            return 1;
