440|                            inBuffer.src = blockTable[blockNb].cPtr;
441|                            inBuffer.size = blockTable[blockNb].cSize;
442|                            inBuffer.pos = 0;
443|                            outBuffer.dst = blockTable[blockNb].resPtr;
444|                            outBuffer.size = blockTable[blockNb].srcSize;
445|                            outBuffer.pos = 0;
