449|                        }
450|                        nbLoops++;
451|                    } while (UTIL_clockSpanMicro(clockStart) < clockLoop);
452|                    ZSTD_freeDStream(zbd);
453|                } else if (compressor == BMK_ZWRAP_ZLIB_REUSE || compressor == BMK_ZWRAP_ZSTD_REUSE || compressor == BMK_ZLIB_REUSE) {
